import React, { useState, useEffect } from "react";
import "./UserDashboard.css";

export default function UserDashboard() {
  const [checkIn, setCheckIn] = useState(null);
  const [checkOut, setCheckOut] = useState(null);
  const [timer, setTimer] = useState("00:00:00");
  const [history, setHistory] = useState([]);
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const [filter, setFilter] = useState("all");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  useEffect(() => {
    const userId = localStorage.getItem("userId");

    if (!userId) {
      window.location.href = "/login";
      return;
    }

    // Load user from localStorage instantly
    const storedUser = localStorage.getItem("currentUser");
    if (storedUser) {
      try {
        setUser(JSON.parse(storedUser));
      } catch (e) {
        console.error("Corrupted user data in localStorage");
      }
    }

    // Fetch attendance history
    fetch(`http://localhost:5000/api/attendance/${userId}`)
      .then((res) => {
        if (!res.ok) throw new Error("Failed to load attendance");
        return res.json();
      })
      .then((data) => setHistory(data))
      .catch((err) => {
        console.error(err);
        setHistory([]);
      })
      .finally(() => setLoading(false));
  }, []);

  // Timer
  useEffect(() => {
    let interval = null;
    if (checkIn && !checkOut) {
      interval = setInterval(() => {
        const diff = Date.now() - checkIn.getTime();
        const hrs = String(Math.floor(diff / 3600000)).padStart(2, "0");
        const mins = String(Math.floor((diff % 3600000) / 60000)).padStart(2, "0");
        const secs = String(Math.floor((diff % 60000) / 1000)).padStart(2, "0");
        setTimer(`${hrs}:${mins}:${secs}`);
      }, 1000);
    } else {
      setTimer("00:00:00");
    }
    return () => clearInterval(interval);
  }, [checkIn, checkOut]);

  const handleCheckIn = () => {
    if (checkIn) return alert("You are already checked in!");
    setCheckIn(new Date());
    setCheckOut(null);
  };

  const handleCheckOut = () => {
    if (!checkIn) return alert("Please check in first!");

    const now = new Date();
    const diffMs = now - checkIn;
    const diffHours = diffMs / (1000 * 60 * 60);

    if (diffHours < 9) {
      const remainingMs = 9 * 3600000 - diffMs;
      const hrs = Math.floor(remainingMs / 3600000);
      const mins = Math.floor((remainingMs % 3600000) / 60000);
      return alert(`⏳ Remaining: ${hrs}h ${mins}m to complete 9 hours`);
    }

    setCheckOut(now);

    const newEntry = {
      date: now.toISOString().split("T")[0],
      checkIn: checkIn.toLocaleTimeString(),
      checkOut: now.toLocaleTimeString(),
      hours: diffHours.toFixed(2),
    };

    setHistory((prev) => [newEntry, ...prev]);
  };

  const filteredHistory = history.filter((item) => {
    const itemDate = new Date(item.date);
    const today = new Date();

    if (filter === "today") return itemDate.toDateString() === today.toDateString();
    if (filter === "month")
      return itemDate.getMonth() === today.getMonth() && itemDate.getFullYear() === today.getFullYear();
    if (filter === "range" && fromDate && toDate)
      return itemDate >= new Date(fromDate) && itemDate <= new Date(toDate);

    return true;
  });

  return (
    <div className="dashboard">
      {/* PROFILE CARD */}
      <div className="profile-card">
        <img src="https://i.imgur.com/4Z7mK2K.png" alt="employee" />
        {loading ? (
          <p>Loading profile...</p>
        ) : user ? (
          <>
            <h2>{user.name || "Employee"}</h2>
            <p>{user.designation || "N/A"}</p>
            <p className="id">{user.id}</p>
          </>
        ) : (
          <p>No user data</p>
        )}

        <button
          className="logout"
          onClick={() => {
            localStorage.clear();
            window.location.href = "/login";
          }}
        >
          Logout
        </button>
      </div>

      {/* ATTENDANCE CARD */}
      <div className="attendance-card">
        <h3>Attendance Dashboard</h3>

        <div className="times">
          <div>
            <span>Check In</span>
            <p>{checkIn ? checkIn.toLocaleTimeString() : "--:--"}</p>
          </div>
          <div>
            <span>Check Out</span>
            <p>{checkOut ? checkOut.toLocaleTimeString() : "--:--"}</p>
          </div>
          <div>
            <span>Working Time</span>
            <p>{timer}</p>
          </div>
        </div>

        <div className="buttons">
          <button onClick={handleCheckIn} disabled={!!checkIn}>
            Check In
          </button>
          <button onClick={handleCheckOut} disabled={!checkIn || !!checkOut}>
            Check Out
          </button>
        </div>

        <div className="filters">
          <button onClick={() => setFilter("all")} className={filter === "all" ? "active" : ""}>
            All
          </button>
          <button onClick={() => setFilter("today")} className={filter === "today" ? "active" : ""}>
            Today
          </button>
          <button onClick={() => setFilter("month")} className={filter === "month" ? "active" : ""}>
            This Month
          </button>

          <div className="date-range">
            <input type="date" value={fromDate} onChange={(e) => setFromDate(e.target.value)} />
            <input type="date" value={toDate} onChange={(e) => setToDate(e.target.value)} />
            <button onClick={() => setFilter("range")} disabled={!fromDate || !toDate}>
              Apply Range
            </button>
          </div>
        </div>

        <table>
          <thead>
            <tr>
              <th>Date</th>
              <th>Check In</th>
              <th>Check Out</th>
              <th>Hours</th>
            </tr>
          </thead>
          <tbody>
            {filteredHistory.length === 0 ? (
              <tr>
                <td colSpan="4">No attendance records found</td>
              </tr>
            ) : (
              filteredHistory.map((item, i) => (
                <tr key={i}>
                  <td>{item.date}</td>
                  <td>{item.checkIn}</td>
                  <td>{item.checkOut || "--"}</td>
                  <td>{item.hours}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
